  Lemma rp_tail : forall (x10 x13 x14 x17 : word) (mY : mem),
    mem_inv asegs mY ->
    munch [(bv_unsigned sp - 112, bv_unsigned sp); (p, p + 8); (mhdr, mhdr + 4); (sh u, sh u + round_up n 8 / 8); (TH + 2840, TH + 2856)]%Z m mY -> wmono asegs m mY ->
